export function useSessionAttendance(sessionId?: string) {
  return useQuery({
    queryKey: ["admin", "attendance", "session", sessionId],
    enabled: !!sessionId,
    queryFn: async (): Promise<SessionAttendanceRecord[]> => {
      const { data, error } = await supabase
        .from("open_play_registrations")
        .select("*")
        .eq("session_id", sessionId!)
        .order("registered_at", { ascending: true });
      if (error) throw error;
      const rows = data ?? [];
      const profiles = await profileMap([...new Set(rows.map((r: any) => r.user_id))]);
      return rows.map((r: any) => ({
        id: r.id,
        user_id: r.user_id,
        full_name: profiles.get(r.user_id)?.full_name || "Unknown",
        phone: profiles.get(r.user_id)?.phone || "—",
        status: r.status,
        payment_status: r.payment_status,
        payment_reference: r.payment_reference,
        waitlist_position: r.waitlist_position,
        registered_at: r.registered_at,
        checked_in_at: r.checked_in_at,
      }));
    },
  });
}

export interface BookingAttendanceRecord {
  id: string;
  reference_code: string | null;
  full_name: string;
  phone: string;
  court_name: string;
  start_time: string;
  end_time: string;
  status: string;
  total_amount: number;
  created_at: string;
  checked_in_at: string | null;
}

export function useBookingAttendance(date?: string) {
  return useQuery({
    queryKey: ["admin", "attendance", "bookings", date],
    enabled: !!date,
    queryFn: async (): Promise<BookingAttendanceRecord[]> => {
      const { data, error } = await supabase
        .from("bookings")
        .select("*, courts(name)")
        .eq("booking_date", date!)
        .order("start_time", { ascending: true });
      if (error) throw error;
      const rows = data ?? [];
      const profiles = await profileMap([...new Set(rows.map((r: any) => r.user_id))]);
      return rows.map((r: any) => ({
        id: r.id,
        reference_code: r.reference_code,
        full_name: profiles.get(r.user_id)?.full_name || "Unknown",
        phone: profiles.get(r.user_id)?.phone || "—",
        court_name: r.courts?.name || "Unknown",
        start_time: r.start_time,
        end_time: r.end_time,
        status: r.status,
        total_amount: r.total_amount,
        created_at: r.created_at,
        checked_in_at: r.checked_in_at,
      }));
    },
  });
}

import { createContext, useContext, useEffect, useState, ReactNode } from "react";
import { User, Session } from "@supabase/supabase-js";
import { supabase } from "@/integrations/supabase/client";

interface AuthContextType {
  user: User | null;
  session: Session | null;
  loading: boolean;
  signUp: (email: string, password: string, fullName: string) => Promise<{ error: Error | null }>;
  signIn: (email: string, password: string) => Promise<{ error: Error | null }>;
  signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    let authChanged = false;
    // Set up auth state listener BEFORE checking session
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      (_event, session) => {
        if (!active) return;
        authChanged = true;
        setSession(session);
        setUser(session?.user ?? null);
        setLoading(false);
      }
    );

    // Check for existing session
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (!active || authChanged) return;
      setSession(session);
      setUser(session?.user ?? null);
      setLoading(false);
    }).catch(() => {
      if (active && !authChanged) setLoading(false);
    });

    return () => { active = false; subscription.unsubscribe(); };
  }, []);

  const signUp = async (email: string, password: string, fullName: string) => {
    const { error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        emailRedirectTo: window.location.origin,
        data: { full_name: fullName },
      },
    });
    return { error };
  };

  const signIn = async (email: string, password: string) => {
    const { error } = await supabase.auth.signInWithPassword({
      email,
      password,
    });
    return { error };
  };

  const signOut = async () => {
    const { error } = await supabase.auth.signOut();
    if (error) throw error;
  };

  return (
    <AuthContext.Provider value={{ user, session, loading, signUp, signIn, signOut }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
};

